from __future__ import absolute_import
from .base_connection import BaseConnection
from hran_radio.exceptions import TelnetConnectionError
import re


class TelnetConnection(BaseConnection):
    def __init__(self, radio_ip, sm_ip, msm_ip, telnet_port):
        super(TelnetConnection, self).__init__(radio_ip, sm_ip, msm_ip)
        self._radio_ip = radio_ip
        self._sm_ip = sm_ip
        self._msm_ip = msm_ip
        self.telnet_port = telnet_port

    def execute_commands(self, cmd, rel):
        """
        Check msm release and next them execute command

        :param cmd: command str
        :return: str
        """
        if rel == "FSMF":
            return self.validate_telnet_output(self.run_command_from_rel3(cmd))
        return self.validate_telnet_output(self.run_command_from_rel4(cmd))

    def wrap_command_for_rel3(self, cmd):
        """
        Return full command prepare to execute from smod rel3 on rmod

        :return: full command
        :rtype: str
        """
        return 'HRAN_RADIO_CMD=$"{}"; {{ echo "$HRAN_RADIO_CMD"; sleep 1; }} | telnet {} {}'.format(
            cmd, self._radio_ip, self.telnet_port
        )

    def wrap_command_for_rel4(self, cmd, num):
        """
        Return full command prepare to execute from smod rel4 on rmod

        :return: full command
        :rtype: str
        """
        return 'HRAN_RADIO_CMD=$"{}"; {{ echo "$HRAN_RADIO_CMD"; sleep 1; }} | lxc-attach -n 0x{}018 telnet {} {}'.format(
            cmd, num, self._radio_ip, self.telnet_port
        )

    @staticmethod
    def validate_telnet_output(telnet_output):
        """
        Check telnet output string

        :param telnet_output: output from telnet command str
        :return: telnet_output
        :rtype: str
        """
        error_pattern = r"Unable to connect to remote host|Connection timed out|telnet: can\'t connect to remote host (.*): No route to host"
        if re.search(error_pattern, telnet_output):
            raise TelnetConnectionError(telnet_output)
        return telnet_output
